WITH valid AS (SELECT id, account_id, amount, txn_time, ROUND(amount, 1) amount_rounded, COALESCE(amount, 0) amount_filled, COALESCE(merchant, 'OTHER') resolved_merchant FROM transactions WHERE merchant IS NOT NULL), gaps AS (SELECT *, CASE WHEN LAG(txn_time) OVER (PARTITION BY account_id ORDER BY txn_time, id) IS NULL OR txn_time > LAG(txn_time) OVER (PARTITION BY account_id ORDER BY txn_time, id) + INTERVAL 60 DAYS THEN 1 ELSE 0 END AS is_new_session FROM valid), sessions_transactions AS (SELECT *, SUM(is_new_session) OVER (PARTITION BY account_id ORDER BY txn_time, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS session_no FROM gaps) SELECT DATE_TRUNC('YEAR', txn_time) AS year_start, DATE_TRUNC('WEEK', txn_time) AS week_start, PERCENTILE_APPROX(amount_filled, ARRAY(0.25, 0.5, 0.75)) AS amount_filled_quartiles, APPROX_PERCENTILE(amount_filled, 0.5) AS amount_filled_p50, COUNT(*) AS row_count, MIN(amount) AS min_amount, MIN(txn_time) AS first_seen, MAX(txn_time) AS ended_at FROM sessions_transactions GROUP BY DATE_TRUNC('YEAR', txn_time), DATE_TRUNC('WEEK', txn_time) HAVING min_amount < 0
